#!/bin/bash
# Downloads every photo off Wix into the images/ folder and points the
# content files at the local copies. Run this ONCE, before you cancel Wix.
#   Mac: open Terminal, type  bash  and a space, drag this file in, press Enter.
#   Safe to run again if anything fails.
cd "$(dirname "$0")/.." || exit 1
echo "Downloading 140 images from Wix..."
fail=0
get() {
  mkdir -p "$(dirname "images/$2")"
  if [ -s "images/$2" ] || curl -sfL --retry 2 -o "images/$2" "$1"; then
    W="$3" L="images/$2" perl -pi -e 's/\Q$ENV{W}\E/$ENV{L}/g' content/*.json
    printf "."
  else
    rm -f "images/$2"; echo; echo "  Could not download images/$2"; fail=1
  fi
}
